 crashFloor=game.World.Height(ExpeditionCrash.X(game.World),ExpeditionCrash.Z)+.1;crashRoot=new Node3D{Name="WontGoAlone",Position=CrashPoint(0,0,0),Rotation=new(0,.6f,0)};worldRoot.AddChild(crashRoot);props.Add(new(){Id="story/crash",Kind=26,Node=crashRoot,Position=crashRoot.Position});
 var paint=new Color(.24f,.34f,.34f);Box(crashRoot,new(0,.6f,0),new(2.2f,.45f,5),paint,true);Box(crashRoot,new(0,1.05f,-1.8f),new(2.15f,.48f,1.5f),paint,true);Bevel(crashRoot,new(0,2.12f,.1f),new(2.1f,.12f,2.7f),paint);Box(crashRoot,new(0,1.5f,-1.23f),new(1.9f,.84f,.05f),new(.12f,.19f,.21f));foreach(float lampX in new[]{-.8f,.8f}){Box(crashRoot,new(lampX,1f,-2.56f),new(.38f,.18f,.04f),new(.72f,.66f,.46f));Box(crashRoot,new(lampX,.85f,2.53f),new(.25f,.14f,.04f),new(.40f,.08f,.06f));}Box(crashRoot,new(0,.81f,-2.56f),new(.7f,.22f,.04f),Ink);
 foreach(float x in new[]{-1f,1f}){foreach(float z in new[]{-1.5f,1.6f}){Ellipsoid(crashRoot,new(x,.48f,z),new(.18f,.48f,.48f),Ink);Ellipsoid(crashRoot,new(x*1.12f,.48f,z),new(.03f,.25f,.25f),Steel);}foreach(float z in new[]{-1.2f,.2f,1.4f})Tube(crashRoot,new(x,.85f,z),new(x,2.1f,z),.045f,Steel);}
 Box(crashRoot,new(0,.89f,.2f),new(1.85f,.16f,1.3f),Cloth);Box(crashRoot,new(0,1.17f,.9f),new(1.85f,.62f,.15f),Cloth);Box(crashRoot,new(-1.1f,.96f,.4f),new(.1f,.45f,1.4f),paint);Box(crashRoot,new(0,.98f,2.1f),new(1.9f,.4f,.6f),Ink,true);
 crashLid=new Node3D{Position=new(0,1.3f,1.7f)};crashRoot.AddChild(crashLid);Box(crashLid,new(0,0,.45f),new(2.13f,.1f,1),paint);
 var girl=LetterPerson(crashRoot,"Sophie",new(.52f,.32f,.65f),true,new(.43f,.33f,.34f));girl.Scale=Vector3.One*.85f;CrashSeat(girl);Box(crashRoot,new(.55f,1.02f,-.25f),new(.23f,.08f,.32f),Cloth);Box(crashRoot,new(.55f,.95f,-.65f),new(.65f,.22f,.35f),Steel,true);
 crashBoy=LetterPerson(crashRoot,"Evan",new(-.35f,.6f,2.23f),false,new(.29f,.33f,.25f));crashBoy.Scale=Vector3.One*.55f;CrashSeat(crashBoy);
 foreach(float x in new[]{-.5f,.5f}){var adult=new Node3D{Position=new(x,.2f,-.55f),Rotation=new(0,0,0)};crashRoot.AddChild(adult);HumanCharacter(adult,2,0,false);adult.Scale=Vector3.One*.82f;CrashSeat(adult);adult.GetNode<Node3D>("Torso").Rotation=new(.18f,0,.1f);}
 // The younger child's silhouette stays covered, without wounds or combat collision.
 Ellipsoid(crashRoot,new(-.55f,1.06f,.45f),new(.26f,.18f,.49f),Cloth);
 crashToy=CrashRabbit(crashRoot,new(.55f,1.03f,2.13f));crashGirlToy=CrashRabbit(crashRoot,new(.58f,1.18f,.37f));
 Box(crashRoot,new(0,.6f,-2.6f),new(2.3f,.18f,.18f),Steel);for(int i=0;i<7;i++)Box(crashRoot,new(-1.5f+i*.4f,.03f,-3-i*.12f),new(.12f,.04f,.18f),new(.55f,.60f,.59f));DrawCrash();}
 void CrashSeat(Node3D n){foreach(string side in new[]{"Left","Right"}){n.GetNode<Node3D>(side+"Leg").Rotation=new(1.35f,0,0);n.GetNode<Node3D>(side+"Leg/Knee").Rotation=new(-1.3f,0,0);n.GetNode<Node3D>(side+"Arm").Rotation=new(-.5f,0,0);n.GetNode<Node3D>(side+"Arm/Elbow").Rotation=new(-.8f,0,0);}}
 Node3D CrashRabbit(Node3D parent,Vector3 at){var n=new Node3D{Name="MilosRabbit",Position=at};parent.AddChild(n);var c=new Color(.66f,.57f,.43f);Ellipsoid(n,new(0,.1f,0),new(.12f,.16f,.08f),c);Ellipsoid(n,new(0,.28f,0),new(.1f,.1f,.08f),c);foreach(float x in new[]{-.055f,.055f}){Ellipsoid(n,new(x,.42f,0),new(.035f,.12f,.035f),c);Ellipsoid(n,new(x,.29f,-.075f),new(.012f,.012f,.01f),Ink);}return n;}
 void DrawCrash(){if(!LetterNodeLive(crashRoot))return;crashLid.Rotation=new(Crash.Opened?-1.7f:0,0,0);crashBoy.Visible=Crash.Opened;crashToy.Visible=Crash.Opened&&!Crash.Toy;crashGirlToy.Visible=Crash.Given;}
 string CrashOperation(){if(!CrashEnabled||dungeon!=null||!LetterNodeLive(crashRoot)||Math.Abs(player.Position.Y-crashFloor)>2)return "";var p=crashRoot.ToLocal(player.Position);if(p.DistanceTo(new Vector3(0,0,3.4f))<2.8)return "trunk";if(p.DistanceTo(new Vector3(1.8f,0,.3f))<2.4)return "girl";return "";}
 string CrashPrompt()=>CrashOperation() switch{"girl"=>"F / SPEAK TO SOPHIE","trunk"=>Crash.Opened?"F / EVAN / MILO'S RABBIT":"F / OPEN THE TRUNK",_=>""};
 bool CrashInteract(){string op=CrashOperation();if(op=="")return false;if(!CoopRequest("crash",op))CrashAction(op);return true;}
 void CrashSync(){game.Persist();if(CoopHost&&coopActors.Count>0)Rpc(nameof(CoopWorldUpdate),Json.Write(WorldSnapshot()));}
 void CrashPage(int page){if(CoopHost&&coopActor>0)RpcId(coopActor,nameof(CoopCrashPanel),page);else ShowCrashPage(page);}
 void CrashAction(string op){if(CoopClient)return;string near=CrashOperation();if(coopCheck)GD.Print($"CRASH ACTION {op} near={near} toy={Crash.Toy} pos={player.Position} floor={crashFloor}");if(op=="girl"&&near=="girl"){Crash.Asked=true;CrashSync();CrashPage(0);return;}if(op=="trunk"&&near=="trunk"){Crash.Opened=true;CrashSync();CrashPage(1);return;}if(op=="take"&&near=="trunk"&&Crash.Opened){Crash.Toy=true;CrashSync();return;}
 if(near!="girl"||!Crash.Toy)return;if(op=="give"&&!Crash.Given)Crash.Given=true;else if((op=="truth"||op=="secret")&&Crash.Given&&Crash.Choice==0)Crash.Choice=op=="truth"?1:2;else return;
 string note="crash/"+(Crash.Choice==1?"truth":Crash.Choice==2?"secret":"rabbit");if(!game.Profile.Journal.Seen.Contains(note))game.Profile.Journal.Seen.Add(note);CrashSync();CrashPage(0);}
 void CrashChoice(string op){CloseMenu();if(!CoopRequest("crash",op))CrashAction(op);}
 void ShowCrashPage(int page){var b=Panel("SO I WON'T GO ALONE");if(page==1){Text(b,"A boy is folded into the luggage space, shaking. He has no bite. Beside him lies a worn stuffed rabbit.\n\nEVAN: 'I heard her calling. I couldn't move. Please. Don't tell her I was here.'");if(!Crash.Toy)Button(b,"TAKE MILO'S RABBIT",()=>CrashChoice("take"));else Text(b,"You have the rabbit. Sophie is still waiting in the back seat.");}
 else{Text(b,Crash.Choice==1?"SOPHIE: 'He was here? All this time?'\n\nShe holds the rabbit close.\n\n'I wish he'd answered. Thank you for answering.'\n\nYou stay beside the car for a while.":Crash.Choice==2?"SOPHIE: 'You found him. Milo never slept without him.'\n\nShe holds the rabbit close.\n\n'Will you stay a minute?'\n\nYou stay beside the car. Evan keeps silent in the trunk.":Crash.Given?"Sophie holds the rabbit with both hands.\n\nSOPHIE: 'Did you find anyone else?'": "Three figures move weakly inside the wreck. Sophie is awake in the back seat, her leg trapped under bent metal. A cloth covers the bite.\n\nSOPHIE: 'I know. Please don't say it. Milo's rabbit is in the trunk. Could you put him in my hands? So I won't go alone.'");if(Crash.Toy&&!Crash.Given)Button(b,"PUT THE RABBIT IN HER HANDS",()=>CrashChoice("give"));if(Crash.Given&&Crash.Choice==0){Button(b,"TELL HER / EVAN IS ALIVE IN THE TRUNK",()=>CrashChoice("truth"));Button(b,"KEEP EVAN'S SECRET / SAY NOTHING ABOUT HIM",()=>CrashChoice("secret"));}if(!Crash.Toy)Text(b,"Search the trunk at the rear of the car.");}Button(b,"NOT YET / LEAVE",CloseMenu);}
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopCrashPanel(int page){if(CoopClient)ShowCrashPage(page);}
 void ShowCrashJournal(){var b=Panel("SO I WON'T GO ALONE / REMEMBERED");Text(b,"Sophie asked for her little brother's stuffed rabbit. Evan was hiding in the trunk, alive and unbit. He asked me to keep his secret.\n\n"+(game.Profile.Journal.Seen.Contains("crash/truth")?"I told her he was there. She wished he had answered her. I stayed beside the car.":game.Profile.Journal.Seen.Contains("crash/secret")?"I kept his secret. She held the rabbit and asked me to stay a minute. I stayed.":"I put Milo's rabbit in her hands. She asked whether I had found anyone else."));Button(b,"BACK",CloseMenu);}
 async Task CrashChecks(){crashFixture=true;game.World.Changes.Crash=new();Teleport(ExpeditionCrash.X(game.World),ExpeditionCrash.Z);SpawnCrash();player.Position=crashRoot.ToGlobal(new Vector3(0,0,3.4f));CrashAction("truth");MigrationChecks.Assert(Crash.Choice==0,"Remote/premature crash choice rejected");CrashAction("trunk");CloseMenu();CrashAction("take");CrashAction("take");MigrationChecks.Assert(Crash.Opened&&Crash.Toy&&!Crash.Given,"Trunk and rabbit one-time state");player.Position=crashRoot.ToGlobal(new Vector3(2,0,.3f));CrashAction("girl");CloseMenu();CrashAction("give");CloseMenu();CrashAction("truth");CloseMenu();CrashAction("secret");MigrationChecks.Assert(Crash.Choice==1&&game.Profile.Journal.Seen.Contains("crash/truth"),"First committed choice wins");var saved=Json.Read<ExpeditionCrash>(Json.Write(Crash));MigrationChecks.Assert(saved.Choice==1&&saved.Given,"Crash save roundtrip");game.World.Changes.Crash.Choice=0;CrashAction("secret");CloseMenu();MigrationChecks.Assert(Crash.Choice==2&&game.Profile.Journal.Seen.Contains("crash/secret"),"Secret branch journal");crashFixture=false;Teleport(0,12);await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);GD.Print("PASS / crash: proximity and progression gates, rabbit, both choices, duplicate protection, save and journals");}
 async void CaptureCrash(){try{crashFixture=true;game.World.Changes.Crash=new();ClearEnemies();game.World.Changes.Time=1050;Teleport(ExpeditionCrash.X(game.World),ExpeditionCrash.Z);SpawnCrash();weaponRoot.Visible=false;player.Position=crashRoot.ToGlobal(new Vector3(3,0,1));camera.GlobalPosition=crashRoot.ToGlobal(new Vector3(6,3,6));camera.LookAt(crashRoot.ToGlobal(new Vector3(0,1,0)));await ArtShot("crash-01-road");Crash.Opened=true;DrawCrash();camera.GlobalPosition=crashRoot.ToGlobal(new Vector3(2.7f,2.8f,4.5f));camera.LookAt(crashRoot.ToGlobal(new Vector3(0,1.5f,2)));await ArtShot("crash-02-trunk");Crash.Toy=true;Crash.Given=true;ShowCrashPage(0);await ArtShot("crash-03-choice");GetTree().Quit();}catch(Exception ex){GD.PushError(ex.ToString());GetTree().Quit(1);}}
